use std::sync::Arc;

use chrono::Utc;
use uuid::Uuid;

use crate::features::credits::domain::{
    CreditError, CreditPack, CreditPurchase, CreditRepository, PurchaseStatus, Wallet,
};
use crate::features::job::application::{PaymentError, PaymentGateway, TokenCharge};
use crate::features::technician::domain::TechnicianRepository;

pub struct PurchaseCreditsInput {
    pub technician_user_id: Uuid,
    pub email: String,
    /// Generated by the app; the idempotency key.
    pub purchase_id: Uuid,
    pub pack_id: String,
    /// Culqi token (`tkn_…` card, `ype_…` Yape) created on the device.
    pub source_id: String,
}

#[derive(Debug, Clone)]
pub struct PurchaseOutcome {
    pub status: PurchaseStatus,
    pub credits_added: i32,
    pub simulated: bool,
    pub wallet: Wallet,
}

pub struct PurchaseCreditsUseCase {
    credit_repo: Arc<dyn CreditRepository>,
    technician_repo: Arc<dyn TechnicianRepository>,
    payment_gateway: Arc<dyn PaymentGateway>,
}

impl PurchaseCreditsUseCase {
    pub fn new(
        credit_repo: Arc<dyn CreditRepository>,
        technician_repo: Arc<dyn TechnicianRepository>,
        payment_gateway: Arc<dyn PaymentGateway>,
    ) -> Self {
        Self { credit_repo, technician_repo, payment_gateway }
    }

    pub async fn execute(&self, input: PurchaseCreditsInput) -> Result<PurchaseOutcome, CreditError> {
        let profile = self
            .technician_repo
            .find_profile_by_user_id(input.technician_user_id)
            .await
            .map_err(|e| CreditError::Repository(e.to_string()))?
            .ok_or(CreditError::NotATechnician)?;
        let pack = CreditPack::find(&input.pack_id).ok_or(CreditError::UnknownPack)?;

        // A retry of a request we already handled answers with what
        // happened the first time — never a second charge.
        if let Some(existing) = self.credit_repo.find_purchase(input.purchase_id).await? {
            if existing.technician_profile_id != profile.id || existing.pack_id != pack.id {
                return Err(CreditError::PurchaseConflict);
            }
            return self.outcome_of(&existing, profile.id).await;
        }

        let purchase = CreditPurchase {
            id: input.purchase_id,
            technician_profile_id: profile.id,
            pack_id: pack.id.to_string(),
            credits: pack.credits,
            amount_cents: pack.price_cents,
            status: PurchaseStatus::Pending,
            gateway: None,
            gateway_reference: None,
            failure_message: None,
            simulated: false,
            created_at: Utc::now(),
        };
        self.credit_repo.create_purchase(&purchase).await?;

        let charge = TokenCharge {
            amount_cents: pack.price_cents,
            email: input.email,
            source_id: input.source_id,
            description: format!("Cerca: {} créditos", pack.credits),
            idempotency_key: purchase.id,
        };

        match self.payment_gateway.charge_token(&charge).await {
            Ok(capture) => {
                self.credit_repo
                    .complete_purchase(purchase.id, &capture.gateway, &capture.gateway_reference, capture.simulated)
                    .await?;
                Ok(PurchaseOutcome {
                    status: PurchaseStatus::Paid,
                    credits_added: pack.credits,
                    simulated: capture.simulated,
                    wallet: self.credit_repo.wallet(profile.id).await?,
                })
            }
            Err(error) => {
                let message = match &error {
                    PaymentError::Rejected { user_message } => user_message.clone(),
                    PaymentError::Declined => "Tu pago fue rechazado. Prueba con otro medio de pago.".to_string(),
                    PaymentError::Unavailable => "El proveedor de pagos no está disponible.".to_string(),
                    PaymentError::Internal(reason) => reason.clone(),
                };
                self.credit_repo.fail_purchase(purchase.id, "psp", &message).await?;
                Err(match error {
                    PaymentError::Unavailable | PaymentError::Internal(_) => CreditError::PaymentUnavailable,
                    PaymentError::Rejected { user_message } => CreditError::PaymentDeclined(user_message),
                    PaymentError::Declined => CreditError::PaymentDeclined(message),
                })
            }
        }
    }

    async fn outcome_of(&self, purchase: &CreditPurchase, technician_profile_id: i32) -> Result<PurchaseOutcome, CreditError> {
        match purchase.status {
            PurchaseStatus::Failed => Err(CreditError::PaymentDeclined(
                purchase
                    .failure_message
                    .clone()
                    .unwrap_or_else(|| "Tu pago fue rechazado.".to_string()),
            )),
            status => Ok(PurchaseOutcome {
                status,
                credits_added: if status == PurchaseStatus::Paid { purchase.credits } else { 0 },
                simulated: purchase.simulated,
                wallet: self.credit_repo.wallet(technician_profile_id).await?,
            }),
        }
    }
}
